condition:
if (ctx.entry.engagement !== 'PART_TIME') return false;
const rate = ctx.entry.terms.rate;
if (rate == null) return false;
return rate.unit === 'HOURLY';

validate:
const employer = (ctx.reads.entity_profile_version ?? []).find(
  (v) =>
    v.status === 'SEALED' &&
    v.effective_range.from <= ctx.entry.effective_range.from &&
    (v.effective_range.to == null || v.effective_range.to >= ctx.entry.effective_range.from),
);
const ext = get(employer, 'entity_extension_data', {});
const region = String(get(ext, 'region', ''));
const regionRows = (ctx.lookup.minimum_wage_by_zone ?? []).filter((r) => r.region === region);
const zone = String(get(ext, 'wage_zone', get(regionRows[0], 'default_zone', '1')));
const table = regionRows.find((r) => r.zone === zone);
const floor = Number(get(table, 'hourly', 0));
return floor > 0 && Number(ctx.entry.terms.rate.amount) >= floor;

const probation = ctx.entry.terms.probation_period;
const limits = ctx.lookup.probation_months;
const engaged = ctx.entry.engagement === 'PART_TIME';
const signed = ctx.entry.signed_contract_period;
let months = limits.open_ended;
if (engaged) months = 0;
else if (signed != null) {
  const length = calendar_completed_months(signed.from, add_days(signed.to, 1));
  months =
    length < limits.minimum_contract ? 0 :
    length < limits.medium_contract ? limits.short :
    length < limits.long_contract ? limits.medium :
    limits.long;
}
if (!(months > 0)) return false;
if (!(probation.from >= ctx.entry.effective_range.from)) return false;
return probation.to < add_months(probation.from, months);

condition:
if (get(ctx.entry.terms, 'probation_period', null) == null) return false;
const rate = get(ctx.entry.terms, 'rate', null);
if (rate == null) return false;
return rate.unit === 'MONTHLY';

validate:
const employer = (ctx.reads.entity_profile_version ?? []).find(
  (v) =>
    v.status === 'SEALED' &&
    v.effective_range.from <= ctx.entry.effective_range.from &&
    (v.effective_range.to == null || v.effective_range.to >= ctx.entry.effective_range.from),
);
const ext = ctx.entry.employee_extension_data ?? {};
const job = get(ext, 'job_salary', null);
const jobValue =
  job == null ? null :
  typeof job === 'number' ? job :
  Number(get(job, 'value', job));
const post = get(ext, 'post_lowest_wage', null);
const rate = Number(ctx.entry.terms.rate.amount);
const comparable =
  jobValue != null ? Number(jobValue) * ctx.lookup.probation_wage_share :
  post != null ? Number(post) :
  null;
const employerExt = get(employer, 'entity_extension_data', {});
const region = String(get(employerExt, 'region', ''));
const regionRows = (ctx.lookup.minimum_wage_by_zone ?? []).filter((r) => r.region === region);
const zone = String(get(employerExt, 'wage_zone', get(regionRows[0], 'default_zone', '1')));
const table = regionRows.find((r) => r.zone === zone);
const floor = Number(get(table, 'monthly', 0));
if (comparable == null) return false;
if (!(floor > 0)) return false;
if (!(rate >= comparable)) return false;
return rate >= floor;

const day = get(ctx.entry.terms, 'normal_hours_per_day', null);
const week = get(ctx.entry.terms, 'normal_hours_per_week', null);
if (day == null && week == null) return false;
if (day != null && !(Number(day) <= 4)) return false;
if (week != null && !(Number(week) <= 24)) return false;
return true;

// 劳部发〔1994〕479号 第三条: 医疗期至多24个月; 劳部发〔1995〕236号 第二条: 特殊疾病24个月内不能痊愈的, 经批准可以适当延长.
const catalog = ctx.reads.leave_catalog.find((row) => row.id === ctx.entry.catalog_id);
if (catalog == null || catalog.code !== 'SICK_LEAVE') return true;
const illnesses = get(ctx.subject.employment, 'events', []).filter((event) => event.kind === 'ILLNESS');
const own = get(ctx.entry, 'leave_catalog_entry_day', []);
const expired = own.some((child) => illnesses.some((event) => event.on <= String(child.incurred_on) && (get(event, 'ended_on', null) == null || String(child.incurred_on) <= event.ended_on) && calendar_completed_months(event.on, String(child.incurred_on)) >= catalog.lookup.medical_period_max_months));
if (expired && get(ctx.subject.employment, 'employee_extension_data.medical_period_extension', null) == null)
  throw 'This illness has run the 24-month medical period. Record the approved extension on the contract first.';
const used =
  sum(
    (ctx.reads.leave_catalog_entry ?? [])
      .filter(
        (e) =>
          e.id !== get(ctx.entry, 'id', '') &&
          get(e, 'reverses', null) == null &&
          e.catalog_id === ctx.entry.catalog_id,
      )
      .map(
        (e) =>
          (ctx.reads.leave_catalog_entry_day ?? []).filter((child) => child.leave_entry_id === e.id).length / 2,
      ),
  ) +
  own.length / 2;
if (used <= ctx.lookup.review_after_days) return true;
return get(ctx.subject.employment, 'employee_extension_data.medical_period_review', null) != null;

const catalog = ctx.reads.leave_catalog[0];
if (catalog == null || catalog.code !== 'WORK_INJURY_LEAVE') return true;
const own = get(ctx.entry, 'leave_catalog_entry_day', []);
const used =
  sum(
    (ctx.reads.leave_catalog_entry ?? [])
      .filter(
        (e) =>
          e.id !== get(ctx.entry, 'id', '') &&
          get(e, 'reverses', null) == null &&
          e.catalog_id === ctx.entry.catalog_id,
      )
      .map(
        (e) =>
          (ctx.reads.leave_catalog_entry_day ?? []).filter((child) => child.leave_entry_id === e.id).length / 2,
      ),
  ) +
  own.length / 2;
if (used <= ctx.lookup.maximum_days) return true;
const contract = ctx.subject.employment;
return get(contract, 'employee_extension_data.work_injury_leave_extension', null) != null;

condition:
const end = get(ctx.entry.effective_range, 'to', null);
if (end == null) return false;
if (end === '') return false;
return !['CONTRACTOR', 'CONSULTANT', 'PAYEE'].includes(ctx.entry.engagement);

validate:
const until = get(ctx.entry.employee_extension_data, 'protected_until', null);
if (until == null) return true;
return String(ctx.entry.effective_range.to) >= String(until);

condition:
const terms = get(ctx.subject.employment, 'terms', {});
const standard = ['STANDARD', ''].includes(String(get(terms, 'statutory_work_category', 'STANDARD')));
const engagement = String(get(ctx.subject.employment, 'engagement', ''));
const dayType = String(get(get(ctx.reads.shift_definition[0], 'variant', {}), 'day_type', 'WORK'));
if (!standard) return false;
if (['CONTRACTOR', 'CONSULTANT', 'PAYEE'].includes(engagement)) return false;
return dayType === 'WORK';

const terms = get(ctx.subject.employment, 'terms', {});
const standard = ['STANDARD', ''].includes(String(get(terms, 'statutory_work_category', 'STANDARD')));
const engagement = String(get(ctx.subject.employment, 'engagement', ''));
return standard && !['CONTRACTOR', 'CONSULTANT', 'PAYEE'].includes(engagement);

validate:
const rows = (ctx.reads.roster_entry ?? []).filter(
  (r) => r.work_date !== ctx.entry.work_date,
);
const worked = rows
  .filter((r) => Array.isArray(r.actual_worked_intervals) && r.actual_worked_intervals.length > 0)
  .map((r) => r.work_date)
  .concat(
    Array.isArray(get(ctx.entry, 'actual_worked_intervals', [])) && get(ctx.entry, 'actual_worked_intervals', []).length > 0
      ? [ctx.entry.work_date]
      : [],
  )
  .toSorted();
const span = ctx.lookup.weekly_rest_days - 1;
return !worked.some((d, i) => i + span < worked.length && worked[i + span] === add_days(d, span));

condition:
const terms = get(ctx.subject.employment, 'terms', {});
return (
  get(ctx.subject.employment, 'engagement', '') === 'PART_TIME' &&
  terms != null
);

validate:
// 劳动合同法 第六十八条: on average at most 4 hours a worked day and at most 24 hours in a week
const monday = add_days(ctx.entry.work_date, -((weekday(ctx.entry.work_date) + 6) % 7));
const sunday = add_days(monday, 6);
const rows = (ctx.reads.roster_entry ?? [])
  .filter((r) => r.work_date !== ctx.entry.work_date)
  .concat([ctx.entry])
  .filter((r) => r.work_date >= monday && r.work_date <= sunday);
const hoursOf = (r) =>
  interval_minutes(get(r, 'actual_worked_intervals', []).filter((span) => get(span, 'end', null) != null)) / 60;
const worked = rows.filter((r) => hoursOf(r) > 0);
const hours = sum(worked.map(hoursOf));
if (hours > 24) return false;
return worked.length === 0 || hours / worked.length <= 4;

condition:
const employment = ctx.subject.employment;
const until = String(get(employment.employee_extension_data, 'nursing_protection_until', ''));
return until !== '' && until >= ctx.entry.work_date;

validate:
const zone = String(get(ctx.subject.employer, 'time_zone', 'Asia/Shanghai'));
const asOf = ctx.entry.work_date + 'T23:59:59Z';
const planned = get(ctx.entry, 'planned_overtime_intervals', []) ?? [];
const actual = get(ctx.entry, 'actual_worked_intervals', []) ?? [];
const night =
  clock_window_minutes(planned, zone, '22:00', '06:00', asOf) +
  clock_window_minutes(actual, zone, '22:00', '06:00', asOf);
return planned.length === 0 && night === 0;

const employment = ctx.subject.employment;
const dob = get(employment.payroll, 'date_of_birth', null);
if (dob == null || dob === '') return false;
if (age_on(dob, ctx.entry.work_date) >= ctx.lookup.minimum_age_years) return true;
return get(employment.employee_extension_data, 'minor_employment_approved', false) === true;

const from = ctx.entry.terms.probation_period.from;
const prior = (ctx.reads.employee_contract ?? []).filter(
  (c) =>
    c.id !== get(ctx.entry, 'id', '') &&
    c.status === 'SEALED' &&
    get(c.terms, 'probation_period', null) != null,
);
return !prior.some((c) => c.terms.probation_period.from !== from);

const prior = (ctx.reads.employee_contract ?? []).filter(
  (c) => c.id !== get(ctx.entry, 'id', '') && c.status === 'SEALED',
);
const earliest = prior
  .map((c) => c.effective_range.from)
  .concat([ctx.entry.effective_range.from])
  .toSorted()[0];
const service = calendar_completed_months(earliest, ctx.entry.signed_contract_period.from);
const required =
  service >= ctx.lookup.service_months ||
  prior.filter((c) => c.signed_contract_period != null).length >=
    ctx.lookup.prior_fixed_terms;
if (!required) return true;
return (ctx.reads.workplace_case_catalog_entry ?? []).some(
  (c) =>
    c.kind === 'FIXED_TERM_CONTRACT_REQUEST' &&
    get(c, 'employment_id', null) === get(ctx.entry, 'id', '') &&
    c.opened_on <= get(c.inputs, 'signed_on', '') &&
    get(c.inputs, 'contract_start', '') === ctx.entry.signed_contract_period.from &&
    get(c.inputs, 'contract_end', '') === ctx.entry.signed_contract_period.to,
);

const terms = ctx.entry.terms;
return (
  ctx.lookup.work_classifications.includes(
    String(get(terms, 'statutory_work_category', '')),
  ) &&
  ctx.lookup.residency_statuses.includes(String(get(terms, 'residency_status', '')))
);

const ext = ctx.entry.employee_extension_data ?? {};
const bad = (ctx.lookup.employee_fields ?? []).some((b) => {
  const value = get(ext, b.field, null);
  if (value == null) return false;
  if (b.minimum != null && Number(value) < b.minimum) return true;
  if (b.maximum != null && Number(value) > b.maximum) return true;
  return b.integer === true && Number(value) !== Math.trunc(Number(value));
});
if (bad) return false;
const retirement = get(ext, 'retirement_category', null);
if (retirement != null && !ctx.lookup.retirement_categories.includes(retirement)) return false;
const schemes = get(ext, 'si_exempt_schemes', []);
if (!Array.isArray(schemes)) return true;
return schemes.every((s) => ctx.lookup.si_exempt_schemes.includes(s));

const ext = ctx.entry.entity_extension_data ?? {};
const bad = (ctx.lookup.entity_fields ?? []).some((b) => {
  const value = get(ext, b.field, null);
  if (value == null) return false;
  if (b.minimum != null && Number(value) < b.minimum) return true;
  if (b.maximum != null && Number(value) > b.maximum) return true;
  return b.integer === true && Number(value) !== Math.trunc(Number(value));
});
if (bad) return false;
const zone = get(ext, 'wage_zone', null);
return zone == null || ctx.lookup.wage_zones.includes(zone);

const reference = String(
  get(ctx.entry.inputs, 'reference', get(ctx.entry.inputs, 'offer_reference', '')),
).trim();
if (reference !== '') return true;
return ctx.entry.evidence_file != null;

return (
  String(get(ctx.entry.inputs, 'signed_on', '')) <= String(ctx.entry.opened_on) &&
  ctx.entry.evidence_file != null
);

const start = String(get(ctx.entry.inputs, 'contract_start', ''));
const end = String(get(ctx.entry.inputs, 'contract_end', ''));
if (start === '') return false;
if (!(end >= start)) return false;
return String(ctx.entry.opened_on) <= start;

const offered = String(get(ctx.entry.inputs, 'offered_on', ''));
const refused = String(get(ctx.entry.inputs, 'refused_on', ''));
const opened = String(ctx.entry.opened_on);
if (offered === '') return false;
if (refused === '') return false;
if (offered > refused) return false;
if (refused > opened) return false;
return ctx.entry.closed_on == null || String(ctx.entry.closed_on) >= refused;

condition:
if (get(ctx.entry, 'encashment', false) === true) return false;
if (get(ctx.entry, 'reverses', null) != null) return false;
return ctx.reads.leave_catalog.some((row) => row.id === ctx.entry.catalog_id && row.code === 'ANNUAL_LEAVE');

validate:
// 职工带薪年休假条例 第四条第(二)至(五)项: 事假累计20天以上且不扣工资, 或病假累计满2、3、4个月的, 不享受当年年休假.
// 企业职工带薪年休假实施办法 第八条: 已休年休假后年度内才出现上述情形的, 不享受下一年度的年休假.
const own = ctx.reads.leave_catalog.find((row) => row.id === ctx.entry.catalog_id);
const codes = Object.fromEntries(ctx.reads.leave_catalog.map((row) => [row.id, row.code]));
const started = get(first(ctx.reads.employee_contract), 'service_started_on', ctx.subject.employment.effective_range.from);
const taken = (code, year) => sum(
  ctx.reads.leave_catalog_entry
    .filter((row) => get(codes, row.catalog_id, '') === code)
    .map((row) => {
      const dayCount = (ctx.reads.leave_catalog_entry_day ?? []).filter(
        (child) => child.leave_entry_id === row.id && String(child.incurred_on).startsWith(year),
      ).length / 2;
      return get(row, 'reverses', null) != null ? -dayCount : dayCount;
    })
);
const barred = (year) => {
  const months = calendar_completed_months(started, year + '-12-31');
  const band = own.lookup.sick_leave_disqualification_days.filter((row) => row.service_months <= months).at(-1);
  return taken('PERSONAL_LEAVE_PAID', year) >= own.lookup.paid_personal_leave_disqualification_days || (band != null && taken('SICK_LEAVE', year) >= band.days);
};
const refused = get(ctx.entry, 'leave_catalog_entry_day', []).some((child) => {
  const year = String(child.incurred_on).slice(0, 4);
  const last = String(Number(year) - 1);
  return barred(year) || (barred(last) && taken('ANNUAL_LEAVE', last) > 0);
});
if (refused) throw 'Personal or sick leave this year, or last year after annual leave was taken, forfeits annual leave.';
return true;

// 上海市女职工劳动保护办法 第八条: 保护作业女职工经期1天公假; 云南省女职工劳动保护特别规定 第九条第三项: 重度痛经确诊后1至2天. One period falls in a calendar month.
const own = ctx.reads.leave_catalog.find((row) => row.id === ctx.entry.catalog_id);
const region = get(ctx.subject.employer, 'entity_extension_data.region', '');
const needs = first(own.lookup.requires_by_region.filter((row) => row.region === region));
const grant = first(own.lookup.days_by_region.filter((row) => row.region === region));
if (needs == null || grant == null || get(ctx.subject.employment, 'employee_extension_data.' + needs.requires, false) !== true)
  throw 'This contract does not hold the fact the local rule requires for menstrual leave.';
const slots = get(ctx.entry, 'leave_catalog_entry_day', []);
const ids = ctx.reads.leave_catalog.filter((row) => row.code === own.code).map((row) => row.id);
const rows = ctx.reads.leave_catalog_entry
  .filter((row) => row.id !== get(ctx.entry, 'id', '') && ids.includes(row.catalog_id))
  .concat([ctx.entry]);
const within = slots.every((child) => {
  const month = String(child.incurred_on).slice(0, 7);
  const taken = sum(rows.map((row) => {
    const held = row.id === ctx.entry.id
      ? slots
      : (ctx.reads.leave_catalog_entry_day ?? []).filter((slot) => slot.leave_entry_id === row.id);
    const dayCount = held.filter((slot) => String(slot.incurred_on).startsWith(month)).length / 2;
    return get(row, 'reverses', null) != null ? -dayCount : dayCount;
  }));
  return taken <= grant.days;
});
if (!within) throw 'Menstrual leave is past the days of this calendar month.';
return true;

// 女职工劳动保护特别规定 第九条第二款: 哺乳未满1周岁婴儿的女职工.
const own = ctx.reads.leave_catalog.find((row) => row.id === ctx.entry.catalog_id);
const births = get(ctx.subject.employment, 'family', []).filter((member) => member.relation === 'CHILD').map((child) => get(child, 'born_on', null)).filter((born) => born != null && born !== '');
const nursing = get(ctx.entry, 'leave_catalog_entry_day', []).every((slot) => births.some((born) => String(born) <= String(slot.incurred_on) && age_on(String(born), String(slot.incurred_on)) < own.lookup.child_age_limit_years));
if (!nursing) throw 'A nursing break needs a child under one on the contract.';
return true;

// 上海市老年人权益保障条例 第二十四条; 云南省老年人权益保障条例 第二十四条: 老年人患病住院治疗期间.
const stays = get(ctx.subject.employment, 'events', []).filter((event) => event.kind === 'PARENT_HOSPITALISATION');
const inside = get(ctx.entry, 'leave_catalog_entry_day', []).every((slot) => stays.some((event) => event.on <= String(slot.incurred_on) && (get(event, 'ended_on', null) == null || String(slot.incurred_on) <= event.ended_on)));
if (!inside) throw 'Elder-care leave falls only while a parent is in hospital. Record the stay as a PARENT_HOSPITALISATION event on the contract first.';
return true;
